WITH filtered AS (SELECT id, plan, start_date, end_date, monthly_fee, status, LENGTH(plan) AS plan_length FROM subscriptions WHERE start_date > DATE '2023-06-19' AND end_date BETWEEN '2023-04-01' AND '2025-07-01') SELECT id, monthly_fee, status, SUM(monthly_fee) OVER (PARTITION BY plan ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_monthly_fee, ROW_NUMBER() OVER w_recent AS row_seq, ROW_NUMBER() OVER w_running AS row_seq_2 FROM filtered WINDOW w_recent AS (PARTITION BY status ORDER BY end_date, id), w_running AS (PARTITION BY plan ORDER BY end_date, id)
